import React, { useEffect, useState } from 'react';
import styles from './Products.module.css';

function Products() {
    const [products, setProducts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [sortBy, setSortBy] = useState('createdAt');
    const [sortOrder, setSortOrder] = useState('desc');
    const [search, setSearch] = useState('');
    const [minPrice, setMinPrice] = useState('');
    const [maxPrice, setMaxPrice] = useState('');
    const [inStock, setInStock] = useState('');

    useEffect(() => {
        const query = new URLSearchParams({
            sortBy,
            sortOrder,
            search,
            minPrice,
            maxPrice,
            inStock
        }).toString();

        fetch(`http://localhost:5000/api/products?${query}&_=${Date.now()}`)
            .then(res => res.json())
            .then(data => {
                setProducts(data.data?.products || []);
                setLoading(false);
            })
            .catch(err => {
                console.error('Ошибка загрузки продуктов:', err);
                setLoading(false);
            });
    }, [sortBy, sortOrder, search, minPrice, maxPrice, inStock]);

    if (loading) {
        return <div className={styles.loading}>Загрузка товаров...</div>;
    }

    return (
        <div className={styles.products}>
            <h2 className={styles.title}>Каталог товаров 🐾</h2>

            <div className={styles.controls}>
                <input
                    type="text"
                    placeholder="Поиск по названию..."
                    value={search}
                    onChange={e => setSearch(e.target.value)}
                />
                <input
                    type="number"
                    placeholder="Мин. цена"
                    value={minPrice}
                    onChange={e => setMinPrice(e.target.value)}
                />
                <input
                    type="number"
                    placeholder="Макс. цена"
                    value={maxPrice}
                    onChange={e => setMaxPrice(e.target.value)}
                />
                <select value={inStock} onChange={e => setInStock(e.target.value)}>
                    <option value="">Все</option>
                    <option value="true">В наличии</option>
                    <option value="false">Нет в наличии</option>
                </select>
                <select value={sortBy} onChange={e => setSortBy(e.target.value)}>
                    <option value="name">Название</option>
                    <option value="sku">Артикул</option>
                    <option value="currentPrice">Цена</option>
                    <option value="createdAt">Дата добавления</option>
                </select>
                <select value={sortOrder} onChange={e => setSortOrder(e.target.value)}>
                    <option value="asc">По возрастанию</option>
                    <option value="desc">По убыванию</option>
                </select>
            </div>

            <div className={styles.grid}>
                {products.map(product => (
                    <div key={product._id} className={styles.card}>
                        <img src={product.imageUrl} alt={product.name} className={styles.image} />
                        <h3>{product.name}</h3>
                        <p><strong>Артикул:</strong> {product.sku}</p>
                        <p><strong>Категория:</strong> {product.category}</p>
                        <p><strong>Для животных:</strong> {product.animalType?.join(', ')}</p>
                        <p><strong>Цена:</strong> {product.currentPrice} ₽ / {product.unit}</p>
                        <p><strong>Остаток:</strong> {product.stockQuantity} шт.</p>
                        <p><strong>Добавлен:</strong> {product.createdAtLocal}</p>
                        <p><strong>Обновлен:</strong> {product.updatedAtLocal}</p>
                        <div className={styles.actions}>
                            <button disabled>Подробнее</button>
                            <button disabled>Редактировать</button>
                            <button disabled>Удалить</button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}

export default Products;
